def adopt_live_campaigns(apps, schema_editor):
    """Preserve existing provider ownership; no provider is contacted by adoption."""
    Contact = apps.get_model('crm', 'Contact')
    Blast = apps.get_model('crm', 'Blast')
    Delivery = apps.get_model('crm', 'BlastDelivery')
    Wave = apps.get_model('crm', 'BlastWave')
    Event = apps.get_model('crm', 'EmailEvent')
    Audit = apps.get_model('crm', 'CrmAuditEvent')
    database = schema_editor.connection.alias
    batch = []
    for contact in Contact.objects.using(database).only('pk', 'email', 'email_domain').iterator():
        contact.email_domain = contact.email.rpartition('@')[2].lower()
        batch.append(contact)
        if len(batch) == 1000:
            Contact.objects.using(database).bulk_update(batch, ['email_domain'])
            batch = []
    if batch:
        Contact.objects.using(database).bulk_update(batch, ['email_domain'])
    for blast in Blast.objects.using(database).filter(status__in=('queued', 'sending')).iterator():
        if 'email' not in (blast.channels or []):
            continue
        if blast.stats and not isinstance(blast.stats, dict):
            raise ValueError('Invalid legacy campaign metadata; review before adoption')
        stats = dict(blast.stats or {})
        email = dict(stats.get('email') or {})
        started = None
        if isinstance(email.get('started_at'), str):
            try:
                started = datetime.fromisoformat(email['started_at'].replace('Z', '+00:00'))
                if started.tzinfo is None:
                    started = started.replace(tzinfo=timezone.utc)
            except ValueError:
                pass
        state = email.get('listmonk_status')
        known = {'finished': 'finished', 'cancelled': 'cancelled', 'paused': 'paused', 'running': 'running'}
        status = known.get(state, 'running' if started else 'loading')
        rows = Delivery.objects.using(database).filter(blast_id=blast.pk, channel='email').order_by('pk')
        wave, created = Wave.objects.using(database).get_or_create(blast_id=blast.pk, index=0, defaults={
            'kind': 'canary', 'status': status, 'size': rows.count(),
            'reserved_at': started or blast.queued_at or blast.created_at,
            'started_at': started, 'finished_at': blast.updated_at if status in ('finished', 'cancelled') else None,
            'listmonk_list_id': blast.listmonk_list_id, 'listmonk_campaign_id': blast.listmonk_campaign_id,
            'stats': {'legacy_adopted': True},
        })
        for rank, delivery in enumerate(rows.iterator()):
            delivery.wave_id, delivery.send_rank = wave.pk, rank
            delivery.save(using=database, update_fields=['wave', 'send_rank'])
        Event.objects.using(database).filter(delivery_id__in=rows.values('pk')).update(wave_id=wave.pk)
        email['wave_legacy_adopted'] = True
        stats['email'] = email
        blast.stats = stats
        blast.save(using=database, update_fields=['stats'])
        if created:
            Audit.objects.using(database).create(action='edit', target_type='blast', target_id=str(blast.pk),
                detail={'operation': 'legacy_wave_adoption', 'wave_index': 0, 'recipients': wave.size})


def reverse_adoption(apps, schema_editor):
    Blast = apps.get_model('crm', 'Blast')
    database = schema_editor.connection.alias
    for blast in Blast.objects.using(database).all().iterator():
        stats = dict(blast.stats or {})
        email = dict(stats.get('email') or {})
        if 'wave_legacy_adopted' in email:
            email.pop('wave_legacy_adopted')
            stats['email'] = email
            blast.stats = stats
            blast.save(using=database, update_fields=['stats'])


